from typing import TypedDict, List, Dict, Any, Optional
from langchain_core.messages import BaseMessage

class GraphState(TypedDict):
    """
    The central state object that is passed around to all agents in the LangGraph pipeline.
    It acts as the shared memory of the entire multi-agent execution.
    """
    analysis_id: str
    repo_url: str
    repo_id: str
    
    # Cached context to avoid re-fetching
    file_tree: List[str]
    pr_diff: Optional[str]
    
    # Agent conversational memory and tool call history
    messages: List[BaseMessage]
    
    # Outputs generated by the agents during their execution
    findings: List[Dict[str, Any]]
    report_draft: str
    eval_scores: Dict[str, float]
    
    # Orchestration metadata
    status: str
    error: Optional[str]
